const fs = require('fs');
const path = require('path');

// ============================================================
// generar_450_chat_completo.js
// ============================================================
// Tres cosas que reporto Casandra usando el chat:
//
// 1. EL TEMA SE QUEDABA PEGADO
//    Despues de preguntar por ansiedad, "¿cuanto pesa?" seguia
//    respondiendo sobre ansiedad. La causa: mi regla trataba cualquier
//    pregunta corta como continuacion, y "¿cuanto pesa?" tiene 12
//    caracteres.
//    Ahora un tema nuevo SIEMPRE le gana al anterior. Solo se continua
//    cuando la pregunta no trae tema propio ("¿y que mas?").
//
// 2. PALABRAS SUELTAS AHORA PREGUNTAN
//    Escribir "heces" o "vomito" a secas puede significar dos cosas
//    distintas. En vez de adivinar, ofrece botones:
//
//      Tú: heces
//      Chiqui: ¿Quieres saber cómo han estado sus heces, o qué
//              significan el color y la forma?
//              [¿Cómo han estado?] [¿Qué significa el color?]
//
//    Cubre: heces, vomito, peso, vacunas, movilidad, ansiedad, agua,
//    alimentacion y temperatura.
//
// 3. LOS CONSEJOS CUBREN LAS 8 CATEGORIAS
//    Antes solo ansiedad, aburrimiento y heces. Ahora tambien
//    movimiento, peso, signos vitales, seguridad (plantas toxicas) y
//    signos de alerta — las mismas categorias que ya existen en Chiqui
//    Tips.
//
//    Y se distingue si la pregunta pide DATOS o pide CONSEJO:
//      "¿ha cojeado?"     -> sus registros
//      "¿por que cojea?"  -> el consejo
//    Sin esa distincion los consejos se comian todas las preguntas por
//    datos.
//
// PENDIENTE: que el veterinario de la familia revise los consejos.
//
// Si algo no calza, ABORTA sin escribir.
// ============================================================

const RUTA = 'components/ChiquiChat.tsx';
const CHAT_B64 = '';

function abortar(motivo) {
  console.log('');
  console.log('ABORTADO: ' + motivo);
  console.log('No se modifico ningun archivo. Avisale a Claude lo que dice este mensaje.');
  process.exit(1);
}

const destino = path.join(process.cwd(), RUTA);
if (!fs.existsSync(destino)) {
  abortar('no se encontro ' + RUTA + '. Corre primero los scripts 440 y 447.');
}

const actual = fs.readFileSync(destino, 'utf8');
if (actual.includes('const AMBIGUAS')) {
  abortar('el chat ya tiene todo esto. Parece que este script ya se corrio.');
}
if (!actual.includes('const ALIMENTOS')) {
  abortar('falta la tabla de alimentos. Corre primero el script 440.');
}

const comp = Buffer.from(CHAT_B64, 'base64').toString('utf8');

const REQUERIDOS = [
  "'use client'",
  'export default function ChiquiChat',
  'const ALIMENTOS',
  'const INTENCIONES',
  'const CONSEJOS',
  'const AMBIGUAS',
  'const pideDatos',
  'el chocolate es tóxico',
  'No soy una inteligencia artificial',
];
for (const r of REQUERIDOS) {
  if (!comp.includes(r)) {
    abortar('el contenido nuevo no incluye [' + r + ']. Script corrupto, no se escribio nada.');
  }
}
// Las 8 categorias de consejos.
const TEMAS = ['ansiedad', 'juego', 'heces', 'movilidad', 'peso', 'vitales', 'seguridad', 'alerta'];
for (const t of TEMAS) {
  if (!comp.includes(`tema: '${t}'`)) {
    abortar('falta la categoria de consejos [' + t + '].');
  }
}
console.log('  OK  las 8 categorias de consejos estan');

const vecesTema = comp.split('type Tema =').length - 1;
if (vecesTema !== 1) {
  abortar('type Tema aparece ' + vecesTema + ' veces. Deberia ser 1.');
}
console.log('  OK  el contenido nuevo esta completo');

fs.writeFileSync(destino, comp, 'utf8');
console.log('');
console.log('OK: ' + RUTA);
console.log('');
console.log('Listo. Cambia de tema, pregunta cuando hay duda, y cubre las 8');
console.log('categorias de Chiqui Tips.');
